INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES
  ('why-upgrading-your-pos-technology-is-essential-for-restaurants', 'The Benefits of Upgrading Your POS Technology', 'Customer expectations shift and technology advances, the restaurant industry must embrace that new technology to stay in competition. Trends indicate that consumers increasingly favor personalization, quickness and...', '[{"type":"p","text":"Customer expectations shift and technology advances, the restaurant industry must embrace that new technology to stay in competition. Trends indicate that consumers increasingly favor personalization, quickness and accuracy: Diners prefer automation, fast yet exceptional service, trendiness, healthy options, and explicitly allergy- and diet-friendly menus."},{"type":"p","text":"Restaurants need to consider these factors when they are Ready to move on from their current POS system? Some of the key features that your new POS should include are:"},{"type":"p","text":"\\- Allergy information at guest’s fingertips"},{"type":"p","text":"\\- Quick order taking through a handheld device"},{"type":"p","text":"\\- Digital receipts"},{"type":"p","text":"\\- Kiosk or tablet ordering"},{"type":"p","text":"\\- Multilingual support"},{"type":"p","text":"Implementing a new POS system can be a big investment for a restaurant. Not only do you have to purchase the hardware and software, but you also need to train your staff on how to use it. However, if you want to stay competitive in the ever-changing restaurant industry, upgrading your POS system is essential. With the right POS system in place, you can improve your guest’s experience, increase efficiency, and make better business decisions."},{"type":"p","text":"If you are looking for a new POS system for your restaurant, be sure to check out eatOS Restaurant POS. eatOS offers all of the features mentioned above and more, making it the perfect POS system for any restaurant."},{"type":"p","text":"Restaurant technology is constantly changing and evolving, so it''s important to stay up-to-date on the latest trends. Upgrading your POS system is a great way to do that. With the right POS system in place, you can improve your guest experience, increase efficiency, and make better business decisions. So what are you waiting for? Upgrade your POS system today!"}]', 'https://static.wixstatic.com/media/35ab20_690a96705492474686ed0e2100d241fe~mv2.jpg', 'Point of Sale', 'eatOS Staff', '2023-06-02', 'published'),
  ('point-of-sale-the-savior-of-small-business', 'Point of Sale: The Savior of Small Business', 'Advanced Point of Sale systems have revolutionized small restaurants by streamlining operations, saving costs, and giving them the opportunity to grow and scale. Shop around for the POS that fits your restaurant’s...', '[{"type":"p","text":"Advanced Point of Sale systems have revolutionized small restaurants by streamlining operations, saving costs, and giving them the opportunity to grow and scale. Shop around for the POS that fits your restaurant’s specific needs, and it will prove an invaluable business tool even as the marketplace evolves."},{"type":"p","text":"QuickOrder on Unsplash"},{"type":"h2","text":"Get More with a Smart Point of Sale"},{"type":"p","text":"While POS terminals used to serve as little more than registers, now they come with so much more. Get a barcode scanner, smart card reader, printers for both the front and back of house. and so much more depending on what your business needs and your budget allows."},{"type":"p","text":"Track your inventory and sales with eatOS technology, which automatically generates relevant sales reports. Identify patterns in traffic and ordering trends so you can strategically price food and deliver quality customer service. Push best-selling dishes or create promotions around menu items that don’t do so well. Do profits tend to dip on Wednesday evenings? Then host an unlimited pasta special based on your customers’ favorite linguini dish to give revenue a boost."},{"type":"p","text":"You can also instantly update your menus to tweak prices or remove sold-out options, thus providing accurate information for the best quality of service."},{"type":"h2","text":"Payment Processing"},{"type":"p","text":"Efficient transactions require eatOS agnostic payment processors, which work faster than your traditional card readers and let you take any kind of payment the customer wants. From mobile wallets to credit cards to tap or swipe to pay, eatOS speeds up the process so customer experiences end on a high note. Never turn down a guest just because you can’t take their preferred payment method."},{"type":"p","text":"eatOS automates accounting too. Don’t have to spend so much time doing it manually and run up exorbitant, unnecessary labor costs. We automatically run payroll, and even consider different pay rates and overtime as well as their tips, so your accounting is fast and efficient every quarter."},{"type":"h2","text":"Scheduling and Workforce Management"},{"type":"p","text":"Creating weekly or biweekly schedules is yet another time-consuming manual task that eats away at your management team’s productivity. With eatOS Point of Sale, you get software integrations with 7Shifts, which not only automates and streamlines scheduling efficiency but makes it easy for your workers to trade shifts online."},{"type":"p","text":"Monitoring sales data lets you see which employees sell the most on average so you can create better marketing strategies and identify who deserves a raise."},{"type":"h2","text":"Diversify Services with a Point of Sale"},{"type":"p","text":"With a smarter system, you can expand your website to offer various new sales opportunities that cater to the marketplace as it’s changed since the pandemic. People now rely more frequently on online options, so why not offer more on your website?"},{"type":"p","text":"1. Collect all the data from delivery, takeout, and curbside services on one comprehensive POS report."},{"type":"p","text":"2. Sell gift cards that guests will redeem when dine-in services resume, thereby keeping them engaged in the meantime."},{"type":"p","text":"3. Offer virtual experiences to make up some profit lost when dine-in services closed, like cooking classes or meal kit subscriptions."},{"type":"p","text":"Photo courtesy of eatOS"},{"type":"p","text":"Small businesses that rely on smart Point of Sale systems can grow and scale freely. With its associated devices, capabilities, and software integrations, restaurants work more efficiently when their POS technology is up to speed."},{"type":"p","text":"eatOS offers an all-in-one cloud-based eco-system exclusively for restaurants. From Point of Sale to Contactless Ordering, Pay & Order at Table, Kitchen Display System, Guest Facing Display, Online Ordering APP / Website and Workforce Management there is everything to help a restaurant succeed no matter the size. Click Here to Schedule a demo to learn more about how your restaurant can make a smooth transition into the world of restaurant technology made simple."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #Restaurant #RestaurantBusiness"}]', 'https://static.wixstatic.com/media/a77ed6_1071183041b24c7c92cb9d676d4f269a~mv2.jpeg', 'Point of Sale', 'eatOS Staff', '2023-06-01', 'published'),
  ('the-right-pos-hardware-for-full-service-restaurants', 'The Right POS Hardware for Full Service Restaurants', 'When it comes to managing your full service restaurant, you need the best of the best technology on the market to effectively handle any obstacle that comes your way. In the food service industry especially, unexpected...', '[{"type":"p","text":"When it comes to managing your full service restaurant, you need the best of the best technology on the market to effectively handle any obstacle that comes your way. In the food service industry especially, unexpected challenges crop up all the time. Having the tools you need to properly overcome any trouble that occurs is vital to smooth operations, and that starts with the right Point of Sale system that supports your customers as well as business."},{"type":"p","text":"Both day-to-day and in the long term, eatOS is here to help bring every full service restaurant up to speed and into the future."},{"type":"h2","text":"Clear Data Means Better Business Decisions"},{"type":"p","text":"Advanced Point of Sale systems like the one powered by eatOS helps everyone in the chain of command, from owners down to every individual server. We track sales data and give real-time, analytic reporting that make it easy to make better decisions. Our heat mapping capabilities identify and highlight trends throughout the day so you can better forecast sales and make applicable business decisions, such as when to schedule more or less staff than usual, menu changes to optimize sales, and more."},{"type":"h2","text":"Reduce Labor Costs"},{"type":"p","text":"Full service restaurants can better manage how much they spend on staffing and labor costs when theyre equipped with the most cutting-edge devices available. Save money instantly just by automating certain aspects of the business. For example, scheduling traditionally takes up a significant amount of effort which in turn costs the business money. Free up managers’ time by investing in eatOS technology, which we’ve integrated with 7Shifts to make it easy for workers to trade shifts with each other, submit time off requests and more, all without bothering management for approvals. Operations run smoother with advanced software and hardware working together with your Point of Sale."},{"type":"h2","text":"Reduce Food Waste"},{"type":"p","text":"eatOS offers inventory management capabilities as well. Track your stock with real-time reporting that lets you know when and what to order so you never have to turn customers away because you’re out of the necessary ingredients that make up their favorite dish. Enhanced communication between the front and back of house also reduces food waste. Knowing what you have in abundance lets you know to order less of it in the future or begin promotional campaigns designed to push sales up for dishes that contain that ingredient. Either way, optimize your money management with inventory tracking."},{"type":"p","text":"When you combine mobile Point of Sales with Kitchen Display Systems, communication within your team reaches all-new heights. Don’t waste money and hurt the environment with excess food waste; let technology bridge the gap."},{"type":"h2","text":"Upselling Capabilities"},{"type":"p","text":"Maximize the potential sales on every customer that comes in. While you can train servers to offer sides and modifications, even the most seasoned worker can forget when theyre in a rush. Our devices automatically prompt upselling to increase the average check size, get servers better tips and improve the guest experience with increased personalization. Customizing every order makes guests feel more understood and valued, thus improving individual customer relationships and encouraging repeat visits."},{"type":"p","text":"Make every order more accurate and get dishes out to their tables faster. Decrease how often food gets sent back or comped while simultaneously encouraging guest loyalty. Even the checkout process runs smoother when you can split bills and items with the press of a button, as tableside ordering and transaction capabilities mean that customers dont have to wait for the check which then improves table turn times too."},{"type":"h2","text":"Better Guest Experience"},{"type":"p","text":"Manage the flow of your customers by strengthening your hold over your service areas. Create a detailed floor plan to help hosts and servers seat customers, give a more accurate estimate about wait times, and handle reservations with ease. Guest management is an extremely important aspect of customer service which is why it’s so vital to meet their needs and expectations, and ensure every experience they have with your restaurant is a good one. With so much competition out there, fostering loyalty should be one of your biggest concerns as a restaurateur."},{"type":"p","text":"That’s why eatOS grows your online ordering channels to encourage more takeout and delivery. Sync these directly with your dine-in sales on the PoS so you always have an accurate, real-time idea of how your business is doing."},{"type":"p","text":"Our cloud-based technology lets you access your restaurant’s data from anywhere as long as there’s an internet connection. This keeps your data secure but accessible so you can run your business without worry. Adjust pricing based on sales data, update the daily special, run promotional campaigns and check on the health of your business on-the-go. We know you’ve got a busy schedule, and eatOS is here to make restaurant management easy. When it comes to managing your full service restaurant, only the best of the best technology will do."},{"type":"p","text":"There’s only one food service technology company that can handle your full service restaurant’s needs. Contact eatOS today and book a demo to find out what else we can do to bring your restaurant into the future."},{"type":"p","text":"#RestaurantTechnologyandCOVID19 #eatOS #PointofSaleforRestaurants #RestaurantBusiness #CloudTechnology #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_f95f5f6f8ba04ba787dc05f667176ff7~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2023-05-30', 'published'),
  ('community-highlight-my-green-lunch', 'Community Highlight: My Green Lunch', 'When Todd Evjenth started My Green Lunch in 2012, he aimed to feed delicious, organic food to local schoolchildren in Silicon Valley. However, once the COVID-19 pandemic touched down in the area and necessitated...', '[{"type":"p","text":"When Todd Evjenth started My Green Lunch in 2012, he aimed to feed delicious, organic food to local schoolchildren in Silicon Valley. However, once the COVID-19 pandemic touched down in the area and necessitated shelter-in-place protocols, there were suddenly no schools in the area to helpbut still plenty of children in need. For that reason, the lunch catering company decided to turn its attention to the community at large."},{"type":"p","text":"In a statement, Evjenth confirmed, “My Green Lunch has completely shifted our focus from providing healthy school lunches to providing healthy emergency meal relief. They’ve partnered with the Office of Education in Santa Clara County as well as Loaves & Fishes Family Kitchen, a soup kitchen in San Jose, to take on the added responsibility of a wider scope. As of 9 April 2020, they’ve fundraised $30K out of their total goal of $300K and provided 5,450 meals to Northern California. Their hope, moving forward, is to perfect the partnership to the point where they can provide 2,500 free meals every week to the Bay Area community."},{"type":"h2","text":"Where do they deliver?"},{"type":"p","text":"When the local schools shut down and My Green Lunch developed their new community outreach plan, they worked hard to adapt quickly so they could return to helping those in need. They repurposed some of their old equipment for new use; their van, for instance, quickly become a staple of the initiative as one of the main ways they bring food to different communities. To supplement what My Green Lunch already had, Loaves & Fishes Family Kitchen similarly repurposed their À La Carte van to cover their portion of the delivery route."},{"type":"p","text":"My Green Lunch and its partners developed a schedule to help both themselves and the communities that they serve. A consistent plan about where they will be on which day allows the partners organize their resources and lets the households that they serve plan out their food intake and storage for the week between deliveries."},{"type":"p","text":"They distribute the food at a different school each day of the week. The Santa Clara County Office of Education also gives out food every Thursday and Friday."},{"type":"h2","text":"What do they serve?"},{"type":"p","text":"My Green Lunch began their initiative as a means of getting healthier food into schools. Their website describes the company as “proud members” of the Community Alliance for Family Farmers, further demonstrating their dedication to helping the public. The page also touts their dedication to “meet the dietary needs and restrictions of all students, including gluten free, nut free (of course!), dairy free, vegetarian, and vegan options in our menu offering.”"},{"type":"p","text":"They have not forgotten their healthy purpose despite shifting from school-aged demographics to the larger community in need. Instead, they’re as fiercely committed to being environmentally friendly as ever and seek to bring that greenness to everyone they now serve. With compost-friendly packaging, napkins and utensils, they maintain a more sustainable carbon footprint and benefit not just the community but the earth as well."},{"type":"h2","text":"How can you help?"},{"type":"p","text":"Although the partnerships with Loaves & Fishes and the Santa Clara County Office of Education give My Green Lunch the resources necessary to reach more people, they still can’t carry out their mission without additional aid. That’s why they’ve set up a GoFundMe campaign so that individuals who can afford it can donate toward the greater good of those less fortunate in their area."},{"type":"p","text":"My Green Lunch’s campaign page states that all donations help them pay “for sourcing ingredients, meal preparation and meal delivery to dedicated drop-off locations” to give contributors a clear idea of where their money goes. These meals are all prepared in a designated kitchen in San Jose, allowing the company to continue sourcing ingredients from local, organic family farms which allows them to not only serve the community and the planet, but these hardworking businesses as well."},{"type":"p","text":"As the donation page states their story, they also make their goals clear: “For every $5 donated, you will be providing 1 meal to someone in need. Our goal of $300,000 will enable My Green Lunch to provide up to 60,000 meals over the course of the COVID-19 pandemic. We can produce 3,000-5,000 meals a day, so with the $300,000 this ensures our ability to provide our target number of meals.”"},{"type":"p","text":"As this pandemic continues and My Green Lunch strives toward their goal of providing 60K meals to Northern California, people with the means and drive to help can show their support by donating to My Green Lunch’s GoFundMe page."},{"type":"p","text":"With schools shut down and many families wondering how best to support and feed their kids, initiatives like the one created by My Green Lunch and its partner organizations double down in their commitment to better the environment, contribute to organic family farms and assist the local communities where they have always dedicated their time. Everyone should strive to prioritize compassion and outreach as we struggle through COVID-19 together, and we can look toward initiatives like the one created by My Green Lunch for good examples of how to proceed."},{"type":"p","text":"#CommunityOutreachStrategies #CoronavirusPandemic #Covid19Pandemic #Delivery #FoodService"}]', 'https://static.wixstatic.com/media/a77ed6_e781a99367ab46608ded6a0b6da7ce84~mv2.jpg', 'Kitchen Operations', 'eatOS Staff', '2023-05-26', 'published'),
  ('consider-partnering-with-these-third-party-apps', 'Consider Partnering With These Third Party Apps', 'Skip to Main Content', '[{"type":"p","text":"Skip to Main Content"},{"type":"p","text":"Delivery has risen in popularity as the COVID-19 pandemic continues. With shelter-in-place measures forcing everyone indoors, making people scared to go to the grocery store and forbidding dine-in services at restaurants across the world, many have increased how often they order in. Most restaurants previously placed their focus on dine-in services and didn’t pay as much attention to delivery. Now, though, that’s the only revenue stream they have coming in."},{"type":"p","text":"Whether you’re new to online ordering services or just shifting focus for the first time, a third party app can massively help your business. Because these apps already have an audience and make it easy to find your restaurant, you don’t have to spend money and time promoting your name. The brand recognition comes with the territory. On top of cutting startup costs and providing you with a built-in customer base, certain third party platforms have particular appeal to restaurants because of partnership benefits Many currently offer additional perks to help restaurants contend with the growing concerns over COVID-19."},{"type":"p","text":"Here are some third party delivery platforms helping out the community, restaurants and customers alike:"},{"type":"h2","text":"1\\. Postmates"},{"type":"p","text":"Postmates published an alert reminding everyone to wash their hands and protect themselves from the potential spread of disease. Aside from this notice, like many platforms they decided to implement a non-contact delivery option. Rather than knocking and handing over an order like usual, workers can now drop off food at the door and let the customer know via text or call that their order has arrived. By giving them the option to eliminate face-to-face contact, delivery workers and customers both avoid the potential spread of infection and abide by the six foot social distancing guideline without compromising service."},{"type":"p","text":"In case someone does fall ill, the app has also created the Postmates Fleet Relief Fund to give workers access to preventative care, testing, medical expenses and check-ups. This ensures the continued wellness and safety of delivery drivers. Drivers can also receive extra assistance from the Fund if they get sick, which covers two weeks’ worth of lost income. To protect their customers, Postmates will also put workers’ accounts on hold if they test positive for COVID-19, a suspension that lasts until the incubation period ends and they make a full, confirmed recovery."},{"type":"p","text":"Postmates has further implemented a Small Business Relief Pilot, currently tested in the San Francisco Bay Area. Small businesses there have waived commission fees so they can deliver to customers at no cost to the business. Postmates is currently looking to expand this program to other areas, too."},{"type":"h2","text":"2\\. Grubhub"},{"type":"p","text":"Grubhub has deferred commission fees for independent restaurants affected by this crisis. CEO Matt Mahoney said, “Delaying our revenue will increase the restaurant’s cash flow, allowing them to pay their employees and weather this difficult situation.” Grubhub has set aside up to $100 million for this endeavor, and restaurants will have as long as four weeks to repay the fees after the suspension gets lifted."},{"type":"p","text":"They also implemented a Smart Promotions feature. For every dollar that restaurants invest in growth, Grubhub will match it. This aims to double the effectiveness of promotion to help restaurants garner business at a time when they need it most."},{"type":"h2","text":"3\\. uber eats"},{"type":"p","text":"Uber Eats waived delivery fees for all of their customers, which encourages them to order from merchants on the app. They further provide free meals to first responders and healthcare workers, demonstrating their appreciation for their work in this extremely difficult time and giving back to them as they help everyone in the community."},{"type":"p","text":"The platform also provides assistance to their workers during this crisis. They’ve also implemented a “leave at the door” delivery option. To further prevent the spread of COVID-19 and other diseases, Uber is giving disinfectant to their workers; as they struggle to meet the demand for sanitation, the company will prioritize those in major cities first in the hopes of curbing the disease in the worst-affected and highest-populated areas."},{"type":"p","text":"When workers do get sick or exposed, Uber Eats suspends the driver’s account and provides them with two weeks of financial assistance to avoid people coming to work sick due to financial concerns and a lack of options."},{"type":"p","text":"They published a safety guide on their website that breaks down how drivers, delivery workers, customers and restaurants can each stay healthy. Along with this, the webpage also provides additional resources so people can support drivers and restaurants during this time."},{"type":"h2","text":"4\\. door dash"},{"type":"p","text":"DoorDash put a twist on contactless delivery by implementing it, not only as an option, but as the default. Customers have to deliberately opt in to face-to-face delivery now, and even still drivers can change over to contactless at any time by simply confirming it with the customer via call or text. This puts power into the workers’ hands and lets them control their own health and safety. Although this, like many of the measures that third party apps have started using, was invented to combat the spread of COVID-19, this feature has the potential to last long after mandatory self-isolation measures lift. People will likely show a lot more caution toward contact and the spread of all diseases in the future."},{"type":"p","text":"If a worker does contract COVID-19 or have to quarantine by law, DoorDash will provide them two weeks’ pay to make up for the lost wages. They also give supplies to workers in areas affected by the disease, such as hand sanitizer, gloves and wipesall highly coveted items in short supply at the grocery store."},{"type":"p","text":"Furthermore, DoorDash aims to assist affected restaurants by earning them a projected $200 million in additional sales this year. For merchants new to the app, DoorDash now offers a 30-day reprieve from commission fees when they sign up. Unlike Grubhub, this is not a deferral but a complete waiver; they never have to pay back those fees. This will greatly help restaurants improve sales and attract customers without worrying about owing a future debt. DoorDash also works with restaurants to help them improve their food prep protocols to ensure that their workers, merchants and customers all stay as safe as possible."},{"type":"p","text":"They have additional benefits for restaurants already on the app. Current partners pay no commission on pick-up orders anymore, and certain eligible merchants will notice a lower commission fee on delivery as well. DoorDash also announced that they aim to add “more than 100,000 independent restaurant partners to DashPass  our subscription program which offers $0 delivery for consumers  for free.” This is huge for restaurants, as DashPass provenly generates a lot more sales than the regular app."},{"type":"p","text":"DoorDash also owns Caviar, another delivery service; by lowering commissions for DashPass merchants and attracting more customers to the platform, Caviar could afford to waive its delivery fee for everyone as well."},{"type":"p","text":"DoorDash further set aside $20 million for merchant marketing to help generate more sales. They’re doing everything they can to support their drivers and help local restaurants stay open, too."},{"type":"p","text":"With quarantines still going strong and people growing more scared to leave the house, delivery apps are a great way to keep your restaurant running despite the closure of dine-in services. These four platforms, along with many others, sacrifice profit in this time of widespread need to help the community and merchant partners that keep them in business."},{"type":"p","text":"Many service providers like eatOS integrate with third party apps like these to keep your restaurant running efficiently. Subscribe with us to learn more about keeping the community safe and healthy."},{"type":"p","text":"#CoronavirusPandemic #OnlineOrdering #FoodService #ThirdPartyApps #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_7403e60787fd4aa4901c712425d7cb68~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2023-05-24', 'published'),
  ('invest-in-developing-your-staff', 'Invest in Developing Your Staff', 'Your staff is the most integral part of your business: They’re the face, hands and lifeblood of the company. This is true of any small business, but low-level employees are especially crucial to the food service...', '[{"type":"p","text":"Your staff is the most integral part of your business: They’re the face, hands and lifeblood of the company. This is true of any small business, but low-level employees are especially crucial to the food service industry which relies on customer service and quality attitudes to really make a customers experience greatthough of course, you need good food, too."},{"type":"p","text":"Considering the high turnover rate in the restaurant industry, which averages around 75% across the board and nearly 150% for QSRs alone according to the 2019 Bureau of Labor Statistics, it makes sense that building an efficient team is even more critical for restaurants than it is for other small businesses. Investing in the professional development of your workers is in your best interest because employees, especially those in the younger generations, overwhelmingly prefer jobs that in some way benefit their professional development. They’re interested in gaining skills that will foster an upwards trajectory throughout their career."},{"type":"p","text":"This drive is valuable to you as well and is a fantastic jumping off point to begin mentoring them in their personal and professional development. Youll end up with better workers who can in turn teach new hires the ropes; investing in this kind of cyclical improvement is especially good, if you can achieve it, because it helps you hang on to employees for longer. In an industry plagued by turnover, that’s difficult to achieve and precious to have."},{"type":"p","text":"How exactly can management invest in developing their staff?"},{"type":"h2","text":"1\\. Set goals"},{"type":"p","text":"Employees can’t improve if they don’t know the standard to which they’re meant to aspire. When they have a tangible goal, they focus on that and become more productive as a result. Thus having relevant, achievable endgames are hugely beneficial to a restaurant. If you can identify the areas that need the most improvement within your establishment, you can begin to set applicable goals to remedy those situations."},{"type":"p","text":"Your objectives can have any time frame, although typically smaller is better. For this reason, quarterly reviews are more beneficial than annual reviews because it’s easier to track progress and see whether these goals are being met, and reassess, reassign goals if necessary, or try alternative strategies for meeting them if the current system doesnt work. Monitoring progress is a careful balance of giving staff time and space to improve but still checking in often enough to track and give feedback on their performance."},{"type":"p","text":"It can be helpful to develop a hiring plan to ensure that these standards continue to be evaluated and met, even years into the future. This will help keep your business fair and on track throughout its duration, even ten years down the line."},{"type":"h2","text":"2\\. Value individual growth"},{"type":"p","text":"In 2014, Glassdoor found that 63% of employees want to learn new skills and train on the same because they consider it one of the most important factors for advancement. Coaching, mentoring and other developmental activities are extremely valued amongst employees as it shows your personal investment in them, which leads to mutual trust and respect."},{"type":"p","text":"Setting a culture of growth and productivity goes a long way because it gives employees the tools they need to perform well. You can guarantee that these methods work because theyll have already been vetted by employees who used those tools to find success themselves. Mentorship can come in many forms from having senior employees train new hires, offering regular training (and follow-up training sessions to brush up on their abilities), or bringing in industry professionals to host seminars and workshops on applicable pathways to success."},{"type":"p","text":"You can also try to encourage outside development in employees’ own time by playing on their desire for professional improvement, though this one is admittedly more difficult to sell. To foster career skills without monetary compensation, employees typically need other incentives, which also come in a variety forms. Team building is often a good place to start, because close bonds with coworkers breeds a better company culture and naturally makes team members want to try harder so as not to become a detriment to the group. Outside reward programs are also effective, such as offering prizes for top sellers in the group or hosting a dinner to show your appreciation for the best shift team. Creativity goes a long way here because it depends on the specific wants and values of the individuals you’re trying to motivate."},{"type":"p","text":"Typically, employees put in as much effort as they’re paid to care about. It’s harsh but true. Minimum wage employeesor sometimes less than minimum wage employees, since tipped workers can make as little as $2.13/hrjust won’t care much about professional development without proper incentive. Raises and benefits remain the best motivator out there."},{"type":"h2","text":"3\\. Review, review, review"},{"type":"p","text":"Setting goals is meaningless without follow-through. Only 2% of employers give ongoing feedback to employees which is unhelpful because it doesn’t tell them whether they’re doing well on a regular enough basis; progress takes a really long time because they can only change their tactics or strengthen the approaches that work once or twice a year. Especially in an industry with turnover so high, most employees probably won’t even last to see a review."},{"type":"p","text":"Take that into consideration with the fact that most people dread yearly reviews, and it’s actually more beneficial to have more informal, frequent reviews. Focus on development, not evaluation, as that only leads to fear of judgement rather than centering on improvement which isn’t the same thing. Asking targeted questions will help to this end, such as, “How can I, as a manager, help you improve?” or “What are your goals and what tools do you need to reach them?” or “How has management helped or hindered your work and success?” This puts the power of self-improvement in their hands and helps you set goals together, while also teaching employees to determine their own areas of professional development that need improvementwhich is a skillset in itself, recognizing weakness and taking steps to do better."},{"type":"p","text":"Creating collaborative, frequent reviews breed happier, more productive and more successful employees."},{"type":"p","text":"Staff are one of the most important, if not the heart, of any restaurant. Respect and personal investment in their development are the keys to building a great staff who will have as much vested interest in giving back to a company who has put so much into helping them grow critical skillsets."},{"type":"p","text":"This is especially important during the COVID-19 pandemic, since you likely have more time to invest in cross-training your employees and building a stronger business in the future when the world reopens. All of this will hopefully lead to lower turnover rates and a more cohesive and agile staff, working together to make your restaurant the best it can be."},{"type":"p","text":"#eatOS #Restaurants #SmallBusiness #Staffing"}]', 'https://static.wixstatic.com/media/a77ed6_24e71d719812452bbe4a6ba367d65c68~mv2.jpeg', 'Workforce Management', 'eatOS Staff', '2023-05-22', 'published'),
  ('orderos-the-future-of-online-ordering', 'orderOS: The Future of Online Ordering', 'Over the past several years, customers have gotten more comfortable with off-premising ordering options. Still, COVID-19 has caused an explosion of favor for takeout and delivery, the likes of which have never been seen...', '[{"type":"p","text":"Over the past several years, customers have gotten more comfortable with off-premising ordering options. Still, COVID-19 has caused an explosion of favor for takeout and delivery, the likes of which have never been seen before."},{"type":"p","text":"Even this far into the pandemic, we still see cases rise all over the country, and new safety regulations come out month to month to month. As a result, restaurants are still closing indoor dining options or just switching over to online platforms. New revenue streams might be just the revitalization that your restaurant needs. Takeout and delivery are undoubtedly here to stay: Affordable pricing and safety concerns have made online ordering a prevalent consumer trend, with many indicating that they plan to continue prioritizing takeout and delivery after the pandemic passes. There are other viruses out there, and considering sanitation and social distance is now, for better or worse, embedded into the modern social consciousness."},{"type":"p","text":"Contactless technology is making its way onto service floors throughout the industry simultaneously, as restaurateurs recognize the rising importance of convenient social distancing. At eatOS, we’ve developed orderOS: A personalized branded website and mobile app that restaurants like you can use to launch your online ordering platform without any of the usual commission fees you get with other third party services."},{"type":"h2","text":"orderOS and the Future of Off-Premise Dining"},{"type":"p","text":"When you sign up with eatOS, we give you complete control over your layout and menu to make business decisions that the most make sense for you. Managing your own system is a huge benefit: When you add curbside services, for example, you can take into account the layout of your restaurant and parking lot when figuring out how to make sure orders go to the right cars in line. You can also optimize your menu to promote best-selling dishes front and center or make sure that it loads conveniently and sensibly on mobile."},{"type":"p","text":"Our mobile and online ordering platforms integrate with your existing system, so sales data continues to update in real-time while incorporating off-premise orders. All tickets automatically go to the Point of Sale and Kitchen Display Screen so cooks can get started immediately on orders, shortening wait times and making much happier customers. This increases the likelihood that each one will want to come back for more."},{"type":"h2","text":"Why Do Customers Love orderOS?"},{"type":"p","text":"What do customers get out of orderOS? They’ll enjoy contactless payment options as well as a more convenient ordering experience. Online and mobile ordering give customers a chance to peruse the full menu and double-check their tickets, meaning increased order accuracy as less gets lost in translation because of human error. orderOS is equipped for easy modifications and add-ons, but checkout notes take it to the next level by giving customers control over the delivery experience."},{"type":"p","text":"Order tracking is also improved with orderOS. Customers can see their orders’ progress in the queue, and workers can give more accurate time estimates for meals and open tables alike."},{"type":"p","text":"We improve the experience even down to each individual transaction. COVID-19 has shown the abject necessity of contactless payment and delivery options; customers can pay at their leisure with self-service, without fear of spreading this deadly virus. eatOS devices are equipped for swipe, tap, near-field communication, and online payments, so customers have the choice to complete the transaction; however, they’re most comfortable doing it."},{"type":"p","text":"When you sign up with eatOS, you’ll see the benefits of a custom branded merchant app and a revitalized online ordering webpage. The future of foodservice is online and mobile: eatOS developed orderOS as the perfect companion to this new dining era."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #Delivery #OnlineOrdering #RestaurantBusiness #Restaurant #FoodServiceTechnologybyeatOS"}]', 'https://static.wixstatic.com/media/a77ed6_4c24bfa7fa78463e9c50b97927eefc6a~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2023-05-19', 'published'),
  ('restaurant-highlight-dig-food-group', 'Restaurant Highlight: Dig Food Group', 'Since Adam Eskin first opened Dig (formerly known as Dig Inn) in 2011, it’s grown into a multifaceted business endeavor that now spans multiple states and involves more than just restaurants. Dig began as a way to...', '[{"type":"p","text":"Since Adam Eskin first opened Dig (formerly known as Dig Inn) in 2011, it’s grown into a multifaceted business endeavor that now spans multiple states and involves more than just restaurants. Dig began as a way to provide healthy, locally-sourced meals to guests and simultaneously support family farms in the community. Now, however, Dig has locations in New York, Boston, Philadelphia, Rye Brook and Brooklyn, and they deliver across Manhattan and Williamsburg."},{"type":"p","text":"On top of building a successful chain of fast-casual restaurants, they’ve undertaken endeavors that necessitated the invention of Dig Food Group. This organization encompasses the restaurant chain as well as Dig Acres Farm, a 12-acre plot in Orange County where they produce their own food. This began as a means to understand more about their friends at the local farms."},{"type":"p","text":"To help people in need during the COVID-19 pandemic, Dig Food Group is also putting their considerable resources toward community relief efforts."},{"type":"h2","text":"Dig Acres Farm Box"},{"type":"p","text":"At Dig, they’re no stranger to community-supported agriculture (also known as CSA). In the summer of 2019, Dig Acres Farm partnered with FoodKick, a same-day fresh food delivery service, to test out using a farm box to get fresh, organic vegetables into the homes of those who needed it. They opened their restaurants for a similar reason, however the farm box allowed them to reach and help more families."},{"type":"p","text":"On March 28th, they relaunched what they’ve dubbed the Dig Acres Farm Box since this pandemic began. Their website describes its contents as “farm-fresh produce from friends of Dig Acres. Selection of 7 - 9 vegetables rotates every Saturday.” Due to the nature of their work, Dig Food Group has connections with many local farmers who, since restaurants all over have shut down, now have an excess of supplies. Many people need these ingredients right now but struggle to find them on grocery shelves. The Dig Acres Farm Box helps local farmers unload and receive compensation for their sudden excess of supplies, and connects them to consumers who need the produce."},{"type":"p","text":"They reopened the farm box for two reasons. Firstly, they recognized that many people rely on grocery delivery but cannot find an available time slot on any of the platforms designed for this service. Thus Dig Food Group decided to be that go-between. Secondly they had already planned to reinstate their farm box this coming summer; however, given the pressing nature of COVID-19 and the unpredictable situation that it has thrust many households into, Dig Food Group decided to open the box earlier than planned so that they could do their part supporting the community. They already had the necessary resources, know-how and systems in place, thus they could reinstitute the farm box when people really needed the supplies."},{"type":"p","text":"The farm box changes every Saturday. Dig Food Group works with their local suppliers to discover what farmers need to unload that week and then design the box accordingly. They list what’s inside underneath the “GET A BOX” button on their website so customers can decide exactly what they need and when they need it."},{"type":"p","text":"The box has already had a major impactful on local communities, so much so that, although they began the endeavor in New York, as of April 24th Dig Food Group announced plans to expand their efforts to cover Philadelphia and Boston as well. Already, farmers and farmers market delivery companies are reaching out to see if they can join the effort. In times like these, we can never extend enough helping hands."},{"type":"h2","text":"Dig Feeds"},{"type":"p","text":"Dig Feeds is another endeavor started by the Dig Food Group. During this crisis, some families need more than healthy ingredients; some also require meals to get them through these tough times. Thus, Dig Food Group launched Dig Feeds."},{"type":"p","text":"According to the website, Dig Feeds aims to “feed people in need during this crisis and beyond. Our farmers and chefs who usually turn vegetables into food for Dig restaurants donate thousands of meals to the people who need them most. 100% of all funds contributed will go to the sourcing, cooking and serving of meals through Dig Feeds.”"},{"type":"p","text":"People in need can request a meal delivery. Those with the means to do so also have the option to gift a meal to somebody else. Dig Feeds is working hard to accommodate all dietary restrictions and allergies to ensure that they can efficiently and effectively help as many people as possible."},{"type":"p","text":"Dig Feeds also launched their “buy a bowl, give a bowl” program to further assist the most vulnerable members of the community. For each order they receive, they also donate a meal to a local hospital, school, homeless shelter, nonprofit, small business or other partner organization in need."},{"type":"p","text":"Over the course of this pandemic,, the Dig Food Group has already donated nearly 100K meals to people in need."},{"type":"h2","text":"Looking toward the future"},{"type":"p","text":"Dig Food Group has worked tirelessly to support local farms and families struggling because of this virus and the strain it has put on people and businesses alike. They have no plans to slow their relief work while COVID-19 continues to threaten society, and in fact hope to support their local farms, practice community relief efforts and get healthy food on consumers’ tables long after the danger has passed."},{"type":"p","text":"Although previous to this pandemic, Dig Food Group’s focus lay in their restaurant chain and organic farm partners, they hope to continue learning about and implementing effective community outreach in the future. As Taylor Lanzet, a member of Dig Food Group, put it: Its not about going back to what we were before, but building a better food system moving forward."},{"type":"p","text":"#CommunityOutreachStrategies #Covid19Pandemic #FoodService #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_5bb8287330774fb893af79d19e5e2eac~mv2.jpg', 'Online Ordering', 'eatOS Staff', '2023-05-17', 'published');
